13:         try {
14:             temporary.outputStream().buffered().use { output ->
15:                 val rows = LegacyImageEncoder.Rows { y, row -> image.getPixels(row, 0, image.width, 0, y, image.width, 1) }
16:                 if (gif) LegacyImageEncoder.gif(image.width, image.height, rows, output, budget, dither)
17:                 else LegacyImageEncoder.bmp(image.width, image.height, rows, output, budget)
