19:             if (!temporary.renameTo(file)) throw IOException(ui(R.string.save20_destination_error))
20:         } catch (error: LegacyImageEncoder.Failure) {
21:             throw IOException(ui(when(error.reason) {
22:                 1 -> R.string.save20_bmp_size_limit
23:                 2 -> R.string.save20_gif_size_limit
