56:     public static long decode(InputStream source, OutputStream destination, long maxBytes) throws IOException {
57:         if (maxBytes < 0) throw new IOException("Invalid decoded-image size limit.");
58:         InputStream input = body(source).input;
59:         int[] group = new int[4]; int count = 0; long written = 0; boolean finished = false;
60:         for (;;) {
61:             int c = input.read(); if (c < 0) break; if (whitespace(c)) continue;
62:             if (finished) throw malformed();
63:             int v = c == '=' ? -2 : value(c); if (v == -1) throw malformed();
64:             group[count++] = v;
65:             if (count == 4) {
66:                 if (group[0] < 0 || group[1] < 0 || (group[2] == -2 && group[3] != -2)) throw malformed();
67:                 int n = group[2] == -2 ? 1 : group[3] == -2 ? 2 : 3;
68:                 if ((n == 1 && (group[1] & 15) != 0) || (n == 2 && (group[2] & 3) != 0)) throw malformed();
69:                 if (n > maxBytes - written) throw new IOException("Decoded image exceeds the import file-size limit.");
70:                 destination.write(group[0] << 2 | group[1] >>> 4);
71:                 if (n >= 2) destination.write(group[1] << 4 | group[2] >>> 2);
72:                 if (n == 3) destination.write(group[2] << 6 | group[3]);
73:                 written += n; count = 0; finished = n != 3;
74:             }
75:         }
76:         if (count != 0) {
77:             if (count == 1 || group[0] < 0 || group[1] < 0 || (count == 3 && group[2] < 0)) throw malformed();
78:             if ((count == 2 && (group[1] & 15) != 0) || (count == 3 && (group[2] & 3) != 0)) throw malformed();
79:             int n = count - 1;
80:             if (n > maxBytes - written) throw new IOException("Decoded image exceeds the import file-size limit.");
81:             destination.write(group[0] << 2 | group[1] >>> 4);
82:             if (n == 2) destination.write(group[1] << 4 | group[2] >>> 2);
83:             written += n;
84:         }
85:         if (written == 0) throw malformed();
86:         return written;
87:     }
